-- Migration: stage Flock 19 Agraharam Potlapally rows from Flock_19.xlsx for diffing against real daily_records (read-only staging, no import into real tables).
CREATE TABLE IF NOT EXISTS public.staging_f19_ap (
  record_date date, shed_no text, open_f int, open_m int, feed_kg_f numeric, feed_kg_m numeric,
  eggs int, he_eggs int, rt_f int, rt_m int, trcull_f int, trcull_m int, mort_f int, mort_m int, close_f int, close_m int
);
SELECT 'staged' AS chk, count(*) AS n FROM public.staging_f19_ap;
